-- Migration: add_ref_task_revenue_rates
-- Source: Revenue Metrics_Duration & Amount (1).xlsx
-- Spec: docs/specs/revenue-rate-sheet.md

CREATE TABLE IF NOT EXISTS reference.ref_task_revenue_rates (
  id              bigint PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
  market_bucket   text NOT NULL,
  task_name       text NOT NULL,
  task_name_norm  text NOT NULL,
  duration_hrs    numeric(5,2) NOT NULL,
  amount_usd      numeric(10,2) NOT NULL,
  source_file     text,
  created_at      timestamptz DEFAULT now(),
  updated_at      timestamptz DEFAULT now(),
  UNIQUE (market_bucket, task_name)
);

CREATE INDEX IF NOT EXISTS idx_revenue_rates_market
  ON reference.ref_task_revenue_rates(market_bucket);
CREATE INDEX IF NOT EXISTS idx_revenue_rates_task_norm
  ON reference.ref_task_revenue_rates(task_name_norm);

